def canonical(cells,rot=True,ref=True):
 pts=list(cells); variations=[]
 for flip in ([1,-1] if ref else [1]):
  for k in range(4 if rot else 1):
   if rot: arr=[]
   else: arr=pts
   if rot:
    for r,c in pts:
     x,y=r, c*flip
     for _ in range(k):x,y=y,-x
     arr.append((x,y))
   else:arr=[(r,c*flip) for r,c in pts]
   mr=min(r for r,c in arr);mc=min(c for r,c in arr)
   variations.append(frozenset((r-mr,c-mc) for r,c in arr))
 return min(variations,key=lambda s:sorted(s))
